using Seamless.Execution.Codecs;
using System.Text;
namespace Seamless.Database.Query;
internal sealed class SqlRowCodec:IAdapter<object?[]>{
    public string FormatId=>"seamless-sql-row-v1";
    public int GetEncodedLength(object?[]value){
        var length=4;foreach(var item in value){var bytes=item switch{null or DBNull=>0,bool or byte=>1,short=>2,int or float or DateOnly=>4,long or double or DateTime or TimeSpan or TimeOnly=>8,decimal or Guid or DateTimeOffset=>16,string text=>StringLength(text),byte[]binary=>checked(4+binary.Length),SqlXmlNode node=>checked(StringLength(node.Document)+StringLength(node.Path)),_=>throw new NotSupportedException("SQL spill codec does not support "+item.GetType())};length=checked(length+1+bytes);}return length;
    }
    private static int StringLength(string value){var bytes=Encoding.UTF8.GetByteCount(value);var prefix=1;for(var remaining=(uint)bytes;remaining>=128;remaining>>=7){prefix++;}return checked(bytes+prefix);}
    public void Encode(object?[]value,Span<byte>destination){using var stream=new MemoryStream();using var writer=new BinaryWriter(stream,Encoding.UTF8,true);Write(writer,value);stream.GetBuffer().AsSpan(0,checked((int)stream.Length)).CopyTo(destination);}
    public object?[]Decode(ReadOnlySpan<byte>source){using var stream=new MemoryStream(source.ToArray(),false);using var reader=new BinaryReader(stream,Encoding.UTF8,true);var count=reader.ReadInt32();if(count<0||count>source.Length){throw new InvalidDataException("Invalid SQL row length.");}var row=new object?[count];for(var i=0;i<count;i++){row[i]=ReadValue(reader);}return row;}
    private static void Write(BinaryWriter writer,object?[]row){writer.Write(row.Length);foreach(var value in row){switch(value){case null:case DBNull:writer.Write((byte)0);break;case bool item:writer.Write((byte)1);writer.Write(item);break;case byte item:writer.Write((byte)2);writer.Write(item);break;case short item:writer.Write((byte)3);writer.Write(item);break;case int item:writer.Write((byte)4);writer.Write(item);break;case long item:writer.Write((byte)5);writer.Write(item);break;case decimal item:writer.Write((byte)6);writer.Write(item);break;case float item:writer.Write((byte)7);writer.Write(item);break;case double item:writer.Write((byte)8);writer.Write(item);break;case string item:writer.Write((byte)9);writer.Write(item);break;case DateTime item:writer.Write((byte)10);writer.Write(item.ToBinary());break;case Guid item:writer.Write((byte)11);writer.Write(item.ToByteArray());break;case byte[]item:writer.Write((byte)12);writer.Write(item.Length);writer.Write(item);break;case TimeSpan item:writer.Write((byte)13);writer.Write(item.Ticks);break;case DateTimeOffset item:writer.Write((byte)14);writer.Write(item.Ticks);writer.Write(item.Offset.Ticks);break;case SqlXmlNode item:writer.Write((byte)15);writer.Write(item.Document);writer.Write(item.Path);break;case DateOnly item:writer.Write((byte)16);writer.Write(item.DayNumber);break;case TimeOnly item:writer.Write((byte)17);writer.Write(item.Ticks);break;default:throw new NotSupportedException("SQL spill codec does not support "+value.GetType());}}}
    private static object?ReadValue(BinaryReader reader)=>reader.ReadByte() switch{0=>null,1=>reader.ReadBoolean(),2=>reader.ReadByte(),3=>reader.ReadInt16(),4=>reader.ReadInt32(),5=>reader.ReadInt64(),6=>reader.ReadDecimal(),7=>reader.ReadSingle(),8=>reader.ReadDouble(),9=>reader.ReadString(),10=>DateTime.FromBinary(reader.ReadInt64()),11=>new Guid(reader.ReadBytes(16)),12=>reader.ReadBytes(reader.ReadInt32()),13=>new TimeSpan(reader.ReadInt64()),14=>new DateTimeOffset(reader.ReadInt64(),new TimeSpan(reader.ReadInt64())),15=>new SqlXmlNode(reader.ReadString(),reader.ReadString()),16=>DateOnly.FromDayNumber(reader.ReadInt32()),17=>new TimeOnly(reader.ReadInt64()),_=>throw new InvalidDataException("Invalid SQL value tag.")};
}
